@app.post("/modules/finance/rules")
def finance_rule_save(keyword: str = Form(...), entry_type: str = Form(...), category: str = Form(...), priority: int = Form(100), access=Depends(require_tenant_user), session: Session = Depends(db)):
    user, tenant = access
    clean_keyword = keyword.strip().casefold()
    if not clean_keyword or len(clean_keyword) > 100 or entry_type not in {"any", "income", "expense"} or category not in FINANCE_CATEGORIES or priority < 0 or priority > 999:
        raise HTTPException(status_code=400, detail="摘要ルールを確認してください")
    rule = session.scalar(select(FinanceCategorizationRule).where(FinanceCategorizationRule.tenant_id == tenant.id, FinanceCategorizationRule.keyword == clean_keyword, FinanceCategorizationRule.entry_type == entry_type))
    if rule:
        rule.category = category; rule.priority = priority; rule.active = True
    else:
        session.add(FinanceCategorizationRule(tenant_id=tenant.id, keyword=clean_keyword, entry_type=entry_type, category=category, priority=priority, created_by_id=user.id))
    session.commit()
    return RedirectResponse("/modules/finance/rules", status_code=303)


@app.post("/modules/finance/rules/{rule_id}/stop")
def finance_rule_stop(rule_id: int, access=Depends(require_tenant_user), session: Session = Depends(db)):
    _, tenant = access
    rule = session.scalar(select(FinanceCategorizationRule).where(FinanceCategorizationRule.id == rule_id, FinanceCategorizationRule.tenant_id == tenant.id, FinanceCategorizationRule.active.is_(True)))
    if not rule:
        raise HTTPException(status_code=404, detail="摘要ルールが見つかりません")
    rule.active = False; session.commit()
    return RedirectResponse("/modules/finance/rules", status_code=303)


@app.get("/modules/finance/statements", response_class=HTMLResponse)
def finance_statements_page(statement_status: str = "", access=Depends(require_tenant_user), session: Session = Depends(db)):
    user, tenant = access
    if statement_status not in {"", "matched", "unmatched"}:
        raise HTTPException(status_code=400, detail="表示条件を確認してください")
    accounts = session.scalars(select(FinanceAccount).where(FinanceAccount.tenant_id == tenant.id).order_by(FinanceAccount.active.desc(), FinanceAccount.id)).all()
    active_accounts = [item for item in accounts if item.active]
    account_names = {item.id: item.name for item in accounts}
    imports = session.scalars(select(FinanceStatementImport).where(FinanceStatementImport.tenant_id == tenant.id).order_by(FinanceStatementImport.imported_at.desc(), FinanceStatementImport.id.desc())).all()
    lines_query = select(FinanceStatementLine).where(FinanceStatementLine.tenant_id == tenant.id)
    if statement_status:
        lines_query = lines_query.where(FinanceStatementLine.status == statement_status)
    lines = session.scalars(lines_query.order_by(FinanceStatementLine.transacted_on.desc(), FinanceStatementLine.id.desc()).limit(200)).all()
    unmatched_total = session.scalar(select(func.count(FinanceStatementLine.id)).where(FinanceStatementLine.tenant_id == tenant.id, FinanceStatementLine.status == "unmatched")) or 0
    matched_total = session.scalar(select(func.count(FinanceStatementLine.id)).where(FinanceStatementLine.tenant_id == tenant.id, FinanceStatementLine.status == "matched")) or 0
    rules = session.scalars(select(FinanceCategorizationRule).where(FinanceCategorizationRule.tenant_id == tenant.id, FinanceCategorizationRule.active.is_(True))).all()
    open_invoices = session.scalars(select(Invoice).where(Invoice.tenant_id == tenant.id, Invoice.status == "issued", Invoice.ledger_entry_id.is_(None)).order_by(Invoice.due_on, Invoice.issued_on, Invoice.id)).all()
    invoice_sale_ids = {item.puppy_sale_id for item in open_invoices}
    invoice_sales = {item.id: item for item in session.scalars(select(PuppySale).where(PuppySale.tenant_id == tenant.id, PuppySale.id.in_(invoice_sale_ids))).all()} if invoice_sale_ids else {}
    account_options = "".join(f'<option value="{item.id}">{html.escape(item.name)}</option>' for item in active_accounts)
    category_options = "".join(f'<option value="{value}">{label}</option>' for value, label in FINANCE_CATEGORIES.items())
    rows = ""; mobile_cards = ""; suggestion_count = 0
    for item in lines:
        state = "照合済み" if item.status == "matched" else "未処理"
        suggestion = finance_rule_suggestion(item, rules) if item.status == "unmatched" else None
        suggestion_count += int(bool(suggestion))
        suggestion_label = f'{FINANCE_CATEGORIES.get(suggestion.category, suggestion.category)}（{html.escape(suggestion.keyword)}）' if suggestion else "候補なし"
        suggested_action = f'''<label><input type="checkbox" name="line_ids" value="{item.id}" form="suggestion-batch">一括対象</label><form method="post" action="/modules/finance/statements/lines/{item.id}/post"><input type="hidden" name="category" value="{suggestion.category}"><button class="success">候補で登録</button></form>''' if suggestion else ""
        manual_action = "" if item.status == "matched" else f'''<form method="post" action="/modules/finance/statements/lines/{item.id}/post"><select name="category" style="width:auto">{category_options}</select><button>費目を選んで登録</button></form>'''
        invoice_candidates = [invoice for invoice in open_invoices if item.status == "unmatched" and item.entry_type == "income" and invoice.amount == item.amount and invoice.issued_on <= item.transacted_on][:20]
        invoice_options = "".join(f'<option value="{invoice.id}">{html.escape(invoice.invoice_no)}／{html.escape(invoice_sales[invoice.puppy_sale_id].customer_name if invoice.puppy_sale_id in invoice_sales else "お客様未登録")}／¥{invoice.amount:,}</option>' for invoice in invoice_candidates)
        invoice_action = f'''<form method="post" action="/modules/finance/statements/lines/{item.id}/settle-invoice"><label>請求書の一致候補</label><select name="invoice_id" style="width:auto">{invoice_options}</select><label><input type="checkbox" name="confirmed" value="true" style="width:auto" required> 請求番号と入金を確認</label><button class="success">請求書へ入金消込</button></form>''' if invoice_candidates else ""
        action = invoice_action + suggested_action + manual_action
        rows += f'<tr><td>{item.transacted_on}</td><td>{html.escape(account_names.get(item.account_id, "口座未登録"))}</td><td>{"入金" if item.entry_type == "income" else "出金"}</td><td>{html.escape(item.description)}</td><td>¥{item.amount:,}</td><td>{suggestion_label}</td><td><span class="badge">{state}</span></td><td>{action or "－"}</td></tr>'
        mobile_cards += f'''<article class="calendar-mobile-card"><h3>{html.escape(item.description)}</h3><p>{item.transacted_on}／{html.escape(account_names.get(item.account_id, "口座未登録"))}／<span class="badge">{state}</span></p><p>{"入金" if item.entry_type == "income" else "出金"} <strong>¥{item.amount:,}</strong></p><p>仕訳候補：<strong>{suggestion_label}</strong></p>{action}</article>'''
    import_rows = "".join(f'<tr><td>{item.imported_at.strftime("%Y-%m-%d %H:%M")}</td><td>{html.escape(account_names.get(item.account_id, "口座未登録"))}</td><td>{html.escape(item.filename)}</td><td>{item.row_count}件</td><td>{item.matched_count}件</td></tr>' for item in imports[:50])
    status_options = "".join(f'<option value="{value}" {"selected" if statement_status == value else ""}>{label}</option>' for value, label in (("", "すべて"), ("unmatched", "未処理"), ("matched", "照合済み")))
    upload_form = f'''<form method="post" action="/modules/finance/statements/import" enctype="multipart/form-data"><div class="grid"><div><label>取込先口座</label><select name="account_id">{account_options}</select></div><div><label>銀行・決済明細CSV（2MB・1,000行まで）</label><input type="file" name="statement_file" accept=".csv,text/csv" required></div></div><button>CSVを取り込んで照合</button></form>''' if active_accounts else '<p class="tenant">先に口座・現金を登録してください。</p>'
    body = f'''<h1>銀行明細CSV取込・自動照合</h1><p>日付・摘要・入金額・出金額を含むCSVを取り込み、既存の台帳記録と自動照合します。UTF-8と一般的な日本語Windows形式に対応します。</p>
    <div class="grid"><div class="module"><h3>照合済み</h3><strong>{matched_total}件</strong></div><div class="module"><h3>未処理</h3><strong class="{'error' if unmatched_total else ''}">{unmatched_total}件</strong></div><div class="module"><h3>表示中の仕訳候補</h3><strong>{suggestion_count}件</strong></div></div>
    <div class="health-toolbar"><a class="button secondary" href="/modules/finance/accounts">口座・現金残高</a><a class="button secondary" href="/modules/finance/receivables">売掛・入金消込</a><a class="button secondary" href="/modules/finance/rules">摘要ルール管理</a><a class="button secondary" href="/modules/finance/reconciliation">残高照合</a></div><h2>CSVを取り込む</h2>{upload_form}
    <p><small>列名例：日付／摘要／入金額／出金額。元ファイルそのものは保存せず、照合に必要な項目だけを保管します。</small></p>
    <h2>取込明細</h2><form method="get"><label>状態</label><select name="statement_status">{status_options}</select><button>表示</button></form><form id="suggestion-batch" method="post" action="/modules/finance/statements/apply-suggestions"><label><input type="checkbox" name="confirmed" value="true" required> 一括対象に選んだ仕訳候補を確認しました</label><button class="success">選択した仕訳候補を一括登録（最大500件）</button></form><div class="calendar-desktop-only" style="overflow-x:auto"><table><tr><th>日付</th><th>口座</th><th>区分</th><th>摘要</th><th>金額</th><th>仕訳候補</th><th>状態</th><th>操作</th></tr>{rows or '<tr><td colspan="8">明細はありません。</td></tr>'}</table></div><section class="calendar-mobile-only">{mobile_cards or '<div class="tenant">明細はありません。</div>'}</section>
    <h2>取込履歴</h2><div style="overflow-x:auto"><table><tr><th>取込日時</th><th>口座</th><th>ファイル</th><th>明細数</th><th>自動照合</th></tr>{import_rows or '<tr><td colspan="5">取込履歴はありません。</td></tr>'}</table></div>'''
    return layout("銀行明細CSV取込・自動照合", body, user)


@app.post("/modules/finance/statements/import")
async def finance_statement_import(account_id: int = Form(...), statement_file: UploadFile = File(...), access=Depends(require_tenant_user), session: Session = Depends(db)):
    user, tenant = access
    account = session.scalar(select(FinanceAccount).where(FinanceAccount.id == account_id, FinanceAccount.tenant_id == tenant.id, FinanceAccount.active.is_(True)))
    filename = Path(statement_file.filename or "statement.csv").name[:255]
    content = await statement_file.read(2 * 1024 * 1024 + 1)
    if not account or len(content) > 2 * 1024 * 1024 or not filename.lower().endswith(".csv"):
        raise HTTPException(status_code=400, detail="口座またはCSVファイルを確認してください")
    content_hash = hashlib.sha256(content).hexdigest()
    duplicate = session.scalar(select(FinanceStatementImport.id).where(FinanceStatementImport.tenant_id == tenant.id, FinanceStatementImport.account_id == account.id, FinanceStatementImport.content_hash == content_hash))
    if duplicate:
        raise HTTPException(status_code=409, detail="同じ口座へ同じCSVが取り込み済みです")
    decoded = None
    for encoding in ("utf-8-sig", "cp932"):
        try:
            decoded = content.decode(encoding); break
        except UnicodeDecodeError:
            continue
    if decoded is None:
        raise HTTPException(status_code=400, detail="CSVの文字コードを確認してください")
    reader = csv.DictReader(io.StringIO(decoded))
    if not reader.fieldnames:
        raise HTTPException(status_code=400, detail="CSVの見出し行が見つかりません")
    normalized = {re.sub(r"[\s_\-]", "", name).lower(): name for name in reader.fieldnames if name}
    def header(*aliases):
        return next((normalized.get(re.sub(r"[\s_\-]", "", value).lower()) for value in aliases if normalized.get(re.sub(r"[\s_\-]", "", value).lower())), None)
    date_header = header("日付", "取引日", "お取引日", "年月日", "date")
    description_header = header("摘要", "内容", "お取引内容", "取引内容", "description")
    income_header = header("入金", "入金額", "お預り金額", "deposit", "income")
    expense_header = header("出金", "出金額", "お支払金額", "withdrawal", "expense")
    if not date_header or not description_header or (not income_header and not expense_header):
        raise HTTPException(status_code=400, detail="CSVには日付・摘要・入金額または出金額の列が必要です")
    parsed_rows = []
    try:
        for row_no, row in enumerate(reader, start=2):
            if row_no > 1001:
                raise HTTPException(status_code=400, detail="CSVは1,000明細以内にしてください")
            if not any((value or "").strip() for value in row.values()):
                continue
            transaction_day = parse_statement_date(row.get(date_header, ""))
            description = (row.get(description_header, "") or "").strip()[:200]
            income = parse_statement_amount(row.get(income_header, "") or "") if income_header else 0
            expense = parse_statement_amount(row.get(expense_header, "") or "") if expense_header else 0
            if transaction_day < date(2000, 1, 1) or transaction_day > date.today() or not description or bool(income) == bool(expense):
                raise ValueError("invalid statement row")
            parsed_rows.append((row_no, transaction_day, "income" if income else "expense", description, income or expense))
    except (ValueError, TypeError):
        raise HTTPException(status_code=400, detail=f"CSVの{row_no}行目を確認してください")
    if not parsed_rows:
        raise HTTPException(status_code=400, detail="取込可能な明細がありません")
    imported = FinanceStatementImport(tenant_id=tenant.id, account_id=account.id, filename=filename, content_hash=content_hash, row_count=len(parsed_rows), imported_by_id=user.id)
    session.add(imported); session.flush(); matched_count = 0
    for row_no, transaction_day, entry_type, description, amount in parsed_rows:
        candidates = session.scalars(select(FinancialEntry).where(FinancialEntry.tenant_id == tenant.id, FinancialEntry.occurred_on == transaction_day, FinancialEntry.entry_type == entry_type, FinancialEntry.amount == amount)).all()
        usable = []
        for candidate in candidates:
            already_used = session.scalar(select(FinanceStatementLine.id).where(FinanceStatementLine.tenant_id == tenant.id, FinanceStatementLine.financial_entry_id == candidate.id))
            assignment = session.scalar(select(FinanceAccountEntry).where(FinanceAccountEntry.financial_entry_id == candidate.id))
            if not already_used and (not assignment or assignment.account_id == account.id):
                usable.append((candidate, assignment))
        matched_entry = usable[0][0] if len(usable) == 1 else None
        if matched_entry and usable[0][1] is None and not finance_period_close(session, tenant.id, transaction_day):
            session.add(FinanceAccountEntry(tenant_id=tenant.id, account_id=account.id, financial_entry_id=matched_entry.id))
        elif matched_entry and usable[0][1] is None:
            matched_entry = None
        status_value = "matched" if matched_entry else "unmatched"
        matched_count += int(bool(matched_entry))
        statement_line = FinanceStatementLine(tenant_id=tenant.id, import_id=imported.id, account_id=account.id, row_no=row_no, transacted_on=transaction_day, entry_type=entry_type, description=description, amount=amount, status=status_value, financial_entry_id=matched_entry.id if matched_entry else None)
        session.add(statement_line); session.flush()
        if matched_entry:
            settlement = session.scalar(select(FinanceReceivableSettlement).where(FinanceReceivableSettlement.tenant_id == tenant.id, FinanceReceivableSettlement.financial_entry_id == matched_entry.id, FinanceReceivableSettlement.statement_line_id.is_(None)))
            if settlement:
                settlement.statement_line_id = statement_line.id
    imported.matched_count = matched_count
    record_finance_audit(session, tenant.id, user.id, "statement_import", "finance_statement_import", imported.id, "銀行明細CSVを取込", f"account={account.id} rows={len(parsed_rows)} matched={matched_count} filename={filename}")
    session.commit()
    return RedirectResponse("/modules/finance/statements?statement_status=unmatched", status_code=303)


@app.post("/modules/finance/statements/apply-suggestions")
def finance_statement_apply_suggestions(confirmed: bool = Form(False), line_ids: list[int] = Form(default=[]), access=Depends(require_tenant_user), session: Session = Depends(db)):
    _, tenant = access
    selected_ids = set(line_ids)
    if not confirmed or not selected_ids or len(selected_ids) > 500:
        raise HTTPException(status_code=400, detail="一括登録する仕訳候補と確認欄を確認してください")
    rules = session.scalars(select(FinanceCategorizationRule).where(FinanceCategorizationRule.tenant_id == tenant.id, FinanceCategorizationRule.active.is_(True))).all()
    lines = session.scalars(select(FinanceStatementLine).where(FinanceStatementLine.tenant_id == tenant.id, FinanceStatementLine.id.in_(selected_ids), FinanceStatementLine.status == "unmatched").order_by(FinanceStatementLine.transacted_on, FinanceStatementLine.id).limit(500)).all()
    accounts = session.scalars(select(FinanceAccount).where(FinanceAccount.tenant_id == tenant.id, FinanceAccount.active.is_(True))).all()
    active_accounts = {account.id: account for account in accounts}
    for line in lines:
        rule = finance_rule_suggestion(line, rules)
        if not rule or line.account_id not in active_accounts or finance_period_close(session, tenant.id, line.transacted_on):
            continue
        entry = FinancialEntry(tenant_id=tenant.id, occurred_on=line.transacted_on, entry_type=line.entry_type, category=rule.category, amount=line.amount, description=line.description, notes=f"摘要ルール #{rule.id}・銀行明細 #{line.import_id}・{line.row_no}行目から確認登録")
        session.add(entry); session.flush()
        session.add(FinanceAccountEntry(tenant_id=tenant.id, account_id=line.account_id, financial_entry_id=entry.id))
        line.status = "matched"; line.financial_entry_id = entry.id
    session.commit()
    return RedirectResponse("/modules/finance/statements?statement_status=unmatched", status_code=303)


@app.post("/modules/finance/statements/lines/{line_id}/post")
def finance_statement_line_post(line_id: int, category: str = Form(...), access=Depends(require_tenant_user), session: Session = Depends(db)):
    _, tenant = access
    line = session.scalar(select(FinanceStatementLine).where(FinanceStatementLine.id == line_id, FinanceStatementLine.tenant_id == tenant.id, FinanceStatementLine.status == "unmatched"))
    account = session.scalar(select(FinanceAccount).where(FinanceAccount.id == line.account_id, FinanceAccount.tenant_id == tenant.id, FinanceAccount.active.is_(True))) if line else None
    if not line or not account or category not in FINANCE_CATEGORIES:
        raise HTTPException(status_code=400, detail="明細または費目を確認してください")
    ensure_finance_period_open(session, tenant.id, line.transacted_on)
    entry = FinancialEntry(tenant_id=tenant.id, occurred_on=line.transacted_on, entry_type=line.entry_type, category=category, amount=line.amount, description=line.description, notes=f"銀行明細取込 #{line.import_id}・{line.row_no}行目から登録")
    session.add(entry); session.flush(); session.add(FinanceAccountEntry(tenant_id=tenant.id, account_id=account.id, financial_entry_id=entry.id))
    line.status = "matched"; line.financial_entry_id = entry.id; session.commit()
    return RedirectResponse("/modules/finance/statements?statement_status=unmatched", status_code=303)


@app.post("/modules/finance/statements/lines/{line_id}/settle-invoice")
def finance_statement_settle_invoice(line_id: int, invoice_id: int = Form(...), confirmed: bool = Form(False), access=Depends(require_tenant_user), session: Session = Depends(db)):
    user, tenant = access
    line = session.scalar(select(FinanceStatementLine).where(FinanceStatementLine.id == line_id, FinanceStatementLine.tenant_id == tenant.id, FinanceStatementLine.status == "unmatched"))
    invoice = session.scalar(select(Invoice).where(Invoice.id == invoice_id, Invoice.tenant_id == tenant.id))
    account = session.scalar(select(FinanceAccount).where(FinanceAccount.id == line.account_id, FinanceAccount.tenant_id == tenant.id, FinanceAccount.active.is_(True))) if line else None
    existing = session.scalar(select(FinanceReceivableSettlement.id).where(FinanceReceivableSettlement.tenant_id == tenant.id, FinanceReceivableSettlement.invoice_id == invoice_id))
    if not confirmed or not line or line.entry_type != "income" or not invoice or invoice.status != "issued" or invoice.ledger_entry_id or existing or not account or invoice.amount != line.amount or line.transacted_on < invoice.issued_on:
        raise HTTPException(status_code=400, detail="銀行明細と請求書の一致内容を確認してください")
    ensure_finance_period_open(session, tenant.id, line.transacted_on)
    settle_invoice_receivable(session, tenant.id, user.id, invoice, account, line.transacted_on, line)
    session.commit()
    return RedirectResponse("/modules/finance/statements?statement_status=unmatched", status_code=303)


@app.post("/modules/finance/accounts")
def finance_account_create(name: str = Form(...), account_type: str = Form(...), opening_balance: int = Form(0), access=Depends(require_tenant_user), session: Session = Depends(db)):
    _, tenant = access; clean_name = name.strip()
    if not clean_name or len(clean_name) > 100 or account_type not in FINANCE_ACCOUNT_TYPES or opening_balance < -999999999 or opening_balance > 999999999:
        raise HTTPException(status_code=400, detail="口座情報を確認してください")
    session.add(FinanceAccount(tenant_id=tenant.id, name=clean_name, account_type=account_type, opening_balance=opening_balance)); session.commit()
    return RedirectResponse("/modules/finance/accounts", status_code=303)


@app.post("/modules/finance/accounts/assign")
def finance_account_assign(financial_entry_id: int = Form(...), account_id: int = Form(...), access=Depends(require_tenant_user), session: Session = Depends(db)):
    _, tenant = access
    entry = session.scalar(select(FinancialEntry).where(FinancialEntry.id == financial_entry_id, FinancialEntry.tenant_id == tenant.id))
    account = session.scalar(select(FinanceAccount).where(FinanceAccount.id == account_id, FinanceAccount.tenant_id == tenant.id, FinanceAccount.active.is_(True)))
    exists = session.scalar(select(FinanceAccountEntry.id).where(FinanceAccountEntry.financial_entry_id == financial_entry_id))
    if not entry or not account or exists:
        raise HTTPException(status_code=400, detail="台帳記録または口座を確認してください")
    ensure_finance_period_open(session, tenant.id, entry.occurred_on)
    session.add(FinanceAccountEntry(tenant_id=tenant.id, account_id=account.id, financial_entry_id=entry.id)); session.commit()
    return RedirectResponse("/modules/finance/accounts", status_code=303)


@app.post("/modules/finance/accounts/transfer")
def finance_account_transfer(transferred_on: str = Form(...), from_account_id: int = Form(...), to_account_id: int = Form(...), amount: int = Form(...), notes: str = Form(""), access=Depends(require_tenant_user), session: Session = Depends(db)):
    user, tenant = access
    try: transfer_day = date.fromisoformat(transferred_on)
    except ValueError: raise HTTPException(status_code=400, detail="振替日を確認してください")
    ensure_finance_period_open(session, tenant.id, transfer_day)
    source = session.scalar(select(FinanceAccount).where(FinanceAccount.id == from_account_id, FinanceAccount.tenant_id == tenant.id, FinanceAccount.active.is_(True)))
    destination = session.scalar(select(FinanceAccount).where(FinanceAccount.id == to_account_id, FinanceAccount.tenant_id == tenant.id, FinanceAccount.active.is_(True)))
    if not source or not destination or source.id == destination.id or amount <= 0 or amount > 999999999 or len(notes) > 500:
        raise HTTPException(status_code=400, detail="振替内容を確認してください")
    transfer = FinanceAccountTransfer(tenant_id=tenant.id, transferred_on=transfer_day, from_account_id=source.id, to_account_id=destination.id, amount=amount, notes=notes.strip() or None)
    session.add(transfer); session.flush()
    record_finance_audit(session, tenant.id, user.id, "account_transfer", "finance_account_transfer", transfer.id, "口座間振替を登録", f"from={source.id} to={destination.id} amount={amount} date={transfer_day}")
    session.commit()
    return RedirectResponse("/modules/finance/accounts", status_code=303)


def finance_export_csv(headers: list[str], rows: list[list]) -> bytes:
    def safe_cell(value) -> str:
        text_value = str(value if value is not None else "").replace("\x00", "").replace("\r", " ").replace("\n", " ")
        return "'" + text_value if text_value.startswith(("=", "+", "-", "@")) else text_value
    output = io.StringIO(newline="")
    writer = csv.writer(output); writer.writerow(headers)
    for row in rows: writer.writerow([safe_cell(value) for value in row])
    return ("\ufeff" + output.getvalue()).encode("utf-8")


