@app.post("/modules/finance/export")
def finance_export_download(year: int = Form(...), admin_password: str = Form(...), confirmed: bool = Form(False), access=Depends(require_tenant_admin), session: Session = Depends(db)):
    user, tenant = access
    if year < 2000 or year > 2100 or not confirmed or not passwords.verify(admin_password, user.password_hash):
        raise HTTPException(status_code=403, detail="対象年、管理者パスワード、確認項目を確認してください")
    year_start, year_end = date(year, 1, 1), date(year, 12, 31)
    entries = session.scalars(select(FinancialEntry).where(FinancialEntry.tenant_id == tenant.id, FinancialEntry.occurred_on >= year_start, FinancialEntry.occurred_on <= year_end).order_by(FinancialEntry.occurred_on, FinancialEntry.id)).all()
    entry_ids = [item.id for item in entries]
    invoices = session.scalars(select(Invoice).where(Invoice.tenant_id == tenant.id, Invoice.issued_on >= year_start, Invoice.issued_on <= year_end).order_by(Invoice.issued_on, Invoice.id)).all()
    expense_requests = session.scalars(select(FinanceExpenseRequest).where(FinanceExpenseRequest.tenant_id == tenant.id, FinanceExpenseRequest.expense_on >= year_start, FinanceExpenseRequest.expense_on <= year_end).order_by(FinanceExpenseRequest.expense_on, FinanceExpenseRequest.id)).all()
    expense_request_ids = [item.id for item in expense_requests]
    expense_documents = session.scalars(select(FinanceExpenseDocument).where(FinanceExpenseDocument.tenant_id == tenant.id, FinanceExpenseDocument.expense_request_id.in_(expense_request_ids)).order_by(FinanceExpenseDocument.id)).all() if expense_request_ids else []
    expense_documents_by_request = {item.expense_request_id: item for item in expense_documents}
    corrections = session.scalars(select(FinanceEntryCorrection).where(FinanceEntryCorrection.tenant_id == tenant.id, (FinanceEntryCorrection.original_entry_id.in_(entry_ids) | FinanceEntryCorrection.reversal_entry_id.in_(entry_ids) | FinanceEntryCorrection.replacement_entry_id.in_(entry_ids))).order_by(FinanceEntryCorrection.corrected_at, FinanceEntryCorrection.id)).all() if entry_ids else []
    allocations = session.scalars(select(CostAllocation).where(CostAllocation.tenant_id == tenant.id, CostAllocation.financial_entry_id.in_(entry_ids)).order_by(CostAllocation.id)).all() if entry_ids else []
    documents = session.scalars(select(FinanceDocument).where(FinanceDocument.tenant_id == tenant.id, FinanceDocument.financial_entry_id.in_(entry_ids)).order_by(FinanceDocument.id)).all() if entry_ids else []
    document_bytes = sum(len(item.file_data) for item in documents) + sum(len(item.file_data) for item in expense_documents)
    if document_bytes > 200 * 1024 * 1024 or len(documents) > 5000 or len(expense_documents) > 5000 or len(documents) + len(expense_documents) > 5000:
        raise HTTPException(status_code=413, detail="証憑の合計容量または件数が安全上限を超えています。期間を分けて管理してください")
    entry_map = {item.id: item for item in entries}
    ledger_csv = finance_export_csv(["ID", "日付", "区分", "費目", "内容", "金額", "メモ"], [[item.id, item.occurred_on, "入金" if item.entry_type == "income" else "経費", FINANCE_CATEGORIES.get(item.category, item.category), item.description, item.amount, item.notes or ""] for item in entries])
    invoice_csv = finance_export_csv(["ID", "請求番号", "発行日", "支払期限", "金額", "状態", "販売案件ID", "台帳ID", "備考"], [[item.id, item.invoice_no, item.issued_on, item.due_on or "", item.amount, INVOICE_STATUSES.get(item.status, item.status), item.puppy_sale_id, item.ledger_entry_id or "", item.notes or ""] for item in invoices])
    expense_request_csv = finance_export_csv(["ID", "経費日", "費目", "内容", "金額", "状態", "申請者ID", "申請メモ", "証憑ファイル名", "承認者ID", "承認日時", "判断コメント", "口座ID", "台帳ID"], [[item.id, item.expense_on, FINANCE_CATEGORIES.get(item.category, item.category), item.description, item.amount, item.status, item.requested_by_id, item.notes or "", expense_documents_by_request[item.id].filename if item.id in expense_documents_by_request else "", item.reviewed_by_id or "", item.reviewed_at.isoformat() if item.reviewed_at else "", item.review_comment or "", item.account_id or "", item.financial_entry_id or ""] for item in expense_requests])
    correction_csv = finance_export_csv(["ID", "元仕訳ID", "反対仕訳ID", "訂正後仕訳ID", "処理", "理由", "実行者ID", "実行日時"], [[item.id, item.original_entry_id, item.reversal_entry_id, item.replacement_entry_id or "", "訂正" if item.correction_type == "replace" else "取消", item.reason, item.corrected_by_id, item.corrected_at.isoformat()] for item in corrections])
    allocation_csv = finance_export_csv(["ID", "台帳ID", "台帳内容", "犬ID", "出産回ID", "配賦額", "メモ"], [[item.id, item.financial_entry_id, entry_map[item.financial_entry_id].description, item.dog_id or "", item.litter_id or "", item.amount, item.notes or ""] for item in allocations])
    extension_by_type = {"application/pdf": "pdf", "image/jpeg": "jpg", "image/png": "png", "image/webp": "webp"}
    document_rows = []; document_files: list[tuple[str, bytes]] = []
    for item in documents:
        archive_name = f'documents/document-{item.id}.{extension_by_type.get(item.content_type, "bin")}'
        entry = entry_map[item.financial_entry_id]
        document_rows.append([item.id, item.financial_entry_id, entry.occurred_on, entry.description, FINANCE_DOCUMENT_TYPES.get(item.document_type, item.document_type), item.issued_by or "", item.document_no or "", item.filename, archive_name])
        document_files.append((archive_name, item.file_data))
    expense_document_files = [(f'expense-request-documents/request-{item.expense_request_id}.{extension_by_type.get(item.content_type, "bin")}', item.file_data) for item in expense_documents]
    documents_csv = finance_export_csv(["ID", "台帳ID", "台帳日付", "台帳内容", "書類種別", "発行元", "書類番号", "元ファイル名", "ZIP内ファイル"], document_rows)
    output = io.BytesIO(); checksums = {}
    with zipfile.ZipFile(output, "w", zipfile.ZIP_DEFLATED) as archive:
        for filename, content in [("ledger.csv", ledger_csv), ("invoices.csv", invoice_csv), ("expense-requests.csv", expense_request_csv), ("entry-corrections.csv", correction_csv), ("cost-allocations.csv", allocation_csv), ("documents.csv", documents_csv), *document_files, *expense_document_files]:
            archive.writestr(filename, content); checksums[filename] = hashlib.sha256(content).hexdigest()
        manifest = {"schema_version": 1, "tenant_id": tenant.id, "tenant_name": tenant.name, "year": year, "exported_at": datetime.now(timezone.utc).isoformat(), "counts": {"ledger": len(entries), "invoices": len(invoices), "expense_requests": len(expense_requests), "expense_request_documents": len(expense_documents), "corrections": len(corrections), "allocations": len(allocations), "documents": len(documents)}, "checksums": checksums}
        archive.writestr("manifest.json", json.dumps(manifest, ensure_ascii=False, indent=2).encode("utf-8"))
    record_operation(session, "finance_export", "success", "会計・証憑一括出力", tenant.id, f"year={year} ledger={len(entries)} invoices={len(invoices)} documents={len(documents)}")
    record_finance_audit(session, tenant.id, user.id, "finance_export", "finance_export", year, "会計・証憑一括出力を実行", f"ledger={len(entries)} invoices={len(invoices)} documents={len(documents)}")
    session.commit()
    return Response(content=output.getvalue(), media_type="application/zip", headers={"Content-Disposition": f'attachment; filename="finance-export-{tenant.id}-{year}.zip"', "Cache-Control": "private, no-store", "X-Content-Type-Options": "nosniff"})


INVOICE_STATUSES = {"draft": "下書き", "issued": "発行済み", "paid": "入金済み", "cancelled": "取消"}


@app.get("/modules/invoices", response_class=HTMLResponse)
def invoices_page(invoice_status: str = "", access=Depends(require_tenant_user), session: Session = Depends(db)):
    user, tenant = access
    if invoice_status not in {"", *INVOICE_STATUSES}:
        raise HTTPException(status_code=400, detail="検索条件を確認してください")
    sales = session.scalars(select(PuppySale).where(PuppySale.tenant_id == tenant.id, PuppySale.status != "cancelled").order_by(PuppySale.id.desc())).all()
    invoices = session.scalars(select(Invoice).where(Invoice.tenant_id == tenant.id).order_by(Invoice.issued_on.desc(), Invoice.id.desc())).all()
    if invoice_status: invoices = [item for item in invoices if item.status == invoice_status]
    sale_options = ""
    for sale in sales:
        dog = session.get(Dog, sale.dog_id); remaining = max((sale.price or 0) - (sale.paid_amount or 0), 0)
        sale_options += f'<option value="{sale.id}">{html.escape(sale.customer_name)}／{html.escape(dog.call_name if dog else "対象犬")}／残額 ¥{remaining:,}</option>'
    status_options = "".join(f'<option value="{value}" {"selected" if invoice_status == value else ""}>{label}</option>' for value, label in (("", "すべて"), *INVOICE_STATUSES.items()))
    rows = ""; mobile_cards = ""
    for invoice in invoices:
        sale = session.scalar(select(PuppySale).where(PuppySale.id == invoice.puppy_sale_id, PuppySale.tenant_id == tenant.id))
        customer_name = sale.customer_name if sale else "販売案件未登録"
        editable_statuses = INVOICE_STATUSES.items() if invoice.status == "paid" else ((key, label) for key, label in INVOICE_STATUSES.items() if key != "paid")
        update_options = "".join(f'<option value="{key}" {"selected" if invoice.status == key else ""}>{label}</option>' for key, label in editable_statuses)
        action = f'''<a class="button secondary" href="/modules/invoices/{invoice.id}.pdf">PDF</a><form method="post" action="/modules/invoices/{invoice.id}/status" style="display:inline"><select name="status" style="width:auto">{update_options}</select><button>更新</button></form>'''
        rows += f'<tr><td>{html.escape(invoice.invoice_no)}</td><td>{invoice.issued_on}</td><td>{html.escape(customer_name)}</td><td>¥{invoice.amount:,}</td><td>{invoice.due_on or "－"}</td><td>{INVOICE_STATUSES[invoice.status]}</td><td>{action}</td></tr>'
        mobile_cards += f'''<article class="calendar-mobile-card"><h3>{html.escape(invoice.invoice_no)}／{html.escape(customer_name)}</h3><p>{invoice.issued_on}　<span class="badge">{INVOICE_STATUSES[invoice.status]}</span></p><p><strong>¥{invoice.amount:,}</strong>／期限 {invoice.due_on or "未設定"}</p><div class="health-toolbar">{action}</div></article>'''
    body = f'''<h1>請求書管理</h1><p>販売案件から請求書を作成し、PDF出力と入金状況を管理します。</p>
    <div class="health-toolbar"><a class="button secondary" href="/modules/sales">販売管理</a><a class="button secondary" href="/modules/finance/receivables">売掛・入金消込</a><a class="button secondary" href="/modules/finance">収支・経費台帳</a></div>
    <h2>請求書を作成</h2>{f'<form method="post" action="/modules/invoices"><div class="grid"><div><label>販売案件</label><select name="sale_id">{sale_options}</select></div><div><label>発行日</label><input type="date" name="issued_on" value="{date.today()}" required></div><div><label>支払期限</label><input type="date" name="due_on"></div><div><label>請求額（税込）</label><input type="number" name="amount" min="1" required></div></div><label>お支払い案内・備考</label><textarea name="notes" maxlength="2000" placeholder="振込先、支払方法、連絡事項など"></textarea><button>請求書を作成</button></form>' if sales else '<p class="error">請求書を作成するには販売案件を登録してください。</p>'}
    <h2>請求書一覧</h2><form method="get" action="/modules/invoices"><label>状態</label><select name="invoice_status">{status_options}</select><button>絞り込む</button> <a class="button secondary" href="/modules/invoices">解除</a></form>
    <div class="calendar-desktop-only" style="overflow-x:auto"><table><tr><th>請求番号</th><th>発行日</th><th>お客様</th><th>請求額</th><th>期限</th><th>状態</th><th>操作</th></tr>{rows or '<tr><td colspan="7">請求書はまだありません。</td></tr>'}</table></div><section class="calendar-mobile-only">{mobile_cards or '<div class="tenant">請求書はまだありません。</div>'}</section>'''
    return layout("請求書管理", body, user)


@app.post("/modules/invoices")
def invoice_create(sale_id: int = Form(...), issued_on: str = Form(...), due_on: str = Form(""), amount: int = Form(...), notes: str = Form(""), access=Depends(require_tenant_user), session: Session = Depends(db)):
    user, tenant = access
    sale = session.scalar(select(PuppySale).where(PuppySale.id == sale_id, PuppySale.tenant_id == tenant.id, PuppySale.status != "cancelled"))
    try:
        issue_day = date.fromisoformat(issued_on); due_day = date.fromisoformat(due_on) if due_on else None
    except ValueError:
        raise HTTPException(status_code=400, detail="日付を確認してください")
    if not sale or amount <= 0 or len(notes) > 2000 or (due_day and due_day < issue_day):
        raise HTTPException(status_code=400, detail="請求情報を確認してください")
    invoice_no = f"INV-{issue_day:%Y%m%d}-{sale.id}-{secrets.token_hex(2).upper()}"
    session.add(Invoice(tenant_id=tenant.id, puppy_sale_id=sale.id, invoice_no=invoice_no, issued_on=issue_day, due_on=due_day, amount=amount, notes=notes.strip() or None))
    session.commit()
    return RedirectResponse("/modules/invoices", status_code=303)


@app.post("/modules/invoices/{invoice_id}/status")
def invoice_status_update(invoice_id: int, status_value: str = Form(..., alias="status"), access=Depends(require_tenant_user), session: Session = Depends(db)):
    _, tenant = access
    invoice = session.scalar(select(Invoice).where(Invoice.id == invoice_id, Invoice.tenant_id == tenant.id))
    if not invoice or status_value not in INVOICE_STATUSES or (invoice.status == "paid" and status_value != "paid"):
        raise HTTPException(status_code=400, detail="請求書の状態を確認してください")
    if status_value == "paid" and not invoice.ledger_entry_id:
        raise HTTPException(status_code=400, detail="入金済みへの変更は売掛金・請求書入金消込から実行してください")
    invoice.status = status_value
    session.commit()
    return RedirectResponse("/modules/invoices", status_code=303)


def invoice_pdf_font() -> str:
    font_name = "NotoSansJP"
    font_path = "/usr/share/fonts/opentype/noto/NotoSansCJK-Regular.ttc"
    if os.path.exists(font_path):
        if font_name not in pdfmetrics.getRegisteredFontNames(): pdfmetrics.registerFont(TTFont(font_name, font_path, subfontIndex=0))
        return font_name
    pdfmetrics.registerFont(UnicodeCIDFont("HeiseiKakuGo-W5"))
    return "HeiseiKakuGo-W5"


def build_invoice_pdf(invoice: Invoice, sale: PuppySale, customer: Customer | None, dog: Dog | None, tenant: Tenant) -> bytes:
    output = io.BytesIO(); font_name = invoice_pdf_font(); pdf = canvas.Canvas(output, pagesize=A4); width, height = A4
    pdf.setTitle(f"請求書 {invoice.invoice_no}"); pdf.setAuthor(tenant.name)
    pdf.setFont(font_name, 22); pdf.drawCentredString(width / 2, height - 55, "請 求 書")
    pdf.setFont(font_name, 9); pdf.drawRightString(width - 42, height - 82, f"請求番号：{invoice.invoice_no}"); pdf.drawRightString(width - 42, height - 98, f"発行日：{invoice.issued_on:%Y年%m月%d日}")
    customer_name = customer.name if customer else sale.customer_name
    pdf.setFont(font_name, 14); pdf.drawString(42, height - 130, f"{customer_name[:35]} 様")
    pdf.setFont(font_name, 9)
    if customer and customer.address: pdf.drawString(42, height - 148, customer.address[:55])
    pdf.drawRightString(width - 42, height - 130, tenant.name[:35]); pdf.drawRightString(width - 42, height - 148, "発行者")
    pdf.setLineWidth(1); pdf.line(42, height - 180, width - 42, height - 180)
    pdf.setFont(font_name, 11); pdf.drawString(52, height - 210, "ご請求金額（税込）")
    pdf.setFont(font_name, 20); pdf.drawRightString(width - 52, height - 210, f"¥{invoice.amount:,}")
    pdf.line(42, height - 228, width - 42, height - 228)
    pdf.setFont(font_name, 10); pdf.drawString(52, height - 260, "請求内容"); pdf.drawString(170, height - 260, f"{dog.call_name if dog else '対象犬'} 販売代金")
    pdf.drawString(52, height - 286, "お支払期限"); pdf.drawString(170, height - 286, invoice.due_on.strftime("%Y年%m月%d日") if invoice.due_on else "別途ご案内")
    pdf.setFillColorRGB(.96, .93, .94); pdf.rect(42, height - 470, width - 84, 140, fill=1, stroke=0); pdf.setFillColorRGB(.2, .15, .17)
    pdf.setFont(font_name, 10); pdf.drawString(55, height - 352, "お支払い案内・備考")
    notes = (invoice.notes or "お支払い方法については発行者へご確認ください。").replace("\r", " ").split("\n")
    y = height - 374; pdf.setFont(font_name, 9)
    for line in notes[:6]: pdf.drawString(55, y, line[:65]); y -= 17
    pdf.setFillColorRGB(.35, .3, .32); pdf.setFont(font_name, 8); pdf.drawCentredString(width / 2, 35, f"{tenant.name} / {invoice.invoice_no}")
    pdf.save(); return output.getvalue()


@app.get("/modules/invoices/{invoice_id}.pdf")
def invoice_pdf(invoice_id: int, access=Depends(require_tenant_user), session: Session = Depends(db)):
    user, tenant = access
    invoice = session.scalar(select(Invoice).where(Invoice.id == invoice_id, Invoice.tenant_id == tenant.id))
    if not invoice: raise HTTPException(status_code=404)
    sale = session.scalar(select(PuppySale).where(PuppySale.id == invoice.puppy_sale_id, PuppySale.tenant_id == tenant.id))
    if not sale: raise HTTPException(status_code=404)
    customer = session.scalar(select(Customer).where(Customer.id == sale.customer_id, Customer.tenant_id == tenant.id)) if sale.customer_id else None
    dog = session.scalar(select(Dog).where(Dog.id == sale.dog_id, Dog.tenant_id == tenant.id))
    content = build_invoice_pdf(invoice, sale, customer, dog, tenant)
    return Response(content=content, media_type="application/pdf", headers={"Content-Disposition": f'attachment; filename="invoice-{invoice.invoice_no}.pdf"', "Cache-Control": "private, no-store"})


@app.get("/modules/costs", response_class=HTMLResponse)
def costs_page(access=Depends(require_tenant_user), session: Session = Depends(db)):
    user, tenant = access
    expenses = session.scalars(select(FinancialEntry).where(FinancialEntry.tenant_id == tenant.id, FinancialEntry.entry_type == "expense").order_by(FinancialEntry.occurred_on.desc(), FinancialEntry.id.desc())).all()
    allocations = session.scalars(select(CostAllocation).where(CostAllocation.tenant_id == tenant.id).order_by(CostAllocation.id.desc())).all()
    dogs = session.scalars(select(Dog).where(Dog.tenant_id == tenant.id).order_by(Dog.call_name)).all()
    litters = session.scalars(select(Litter).where(Litter.tenant_id == tenant.id).order_by(Litter.birth_date.desc(), Litter.id.desc())).all()
    dogs_by_id = {item.id: item for item in dogs}; litters_by_id = {item.id: item for item in litters}
    allocated_by_entry: dict[int, int] = {}
    for item in allocations: allocated_by_entry[item.financial_entry_id] = allocated_by_entry.get(item.financial_entry_id, 0) + item.amount
    remaining_expenses = [(item, item.amount - allocated_by_entry.get(item.id, 0)) for item in expenses if item.amount - allocated_by_entry.get(item.id, 0) > 0]
    expense_options = "".join(f'<option value="{item.id}">{item.occurred_on}／{html.escape(item.description)}／未配賦 ¥{remaining:,}</option>' for item, remaining in remaining_expenses)
    dog_options = '<option value="">犬へ配賦しない</option>' + "".join(f'<option value="{item.id}">{html.escape(item.call_name)}／{html.escape(item.registered_name or "血統名未登録")}</option>' for item in dogs)
    litter_options = '<option value="">出産回へ配賦しない</option>'
    for litter in litters:
        dam = dogs_by_id.get(litter.dam_id) or session.get(Dog, litter.dam_id)
        litter_options += f'<option value="{litter.id}">{litter.birth_date}／{html.escape(dam.call_name if dam else "母犬未登録")}／{litter.alive_count}頭</option>'
    sales = session.scalars(select(PuppySale).where(PuppySale.tenant_id == tenant.id, PuppySale.status != "cancelled")).all()
    sales_by_dog: dict[int, list[PuppySale]] = {}
    for sale in sales: sales_by_dog.setdefault(sale.dog_id, []).append(sale)
    planned_total = received_total = cost_total = 0; rows = ""; mobile_cards = ""
    for litter in litters:
        dam = dogs_by_id.get(litter.dam_id) or session.get(Dog, litter.dam_id)
        puppies = [dog for dog in dogs if dog.category == "puppy" and dog.dam_id == litter.dam_id and dog.birth_date == litter.birth_date]
        litter_sales = [sale for puppy in puppies for sale in sales_by_dog.get(puppy.id, [])]
        planned = sum(sale.price or 0 for sale in litter_sales); received = sum(sale.paid_amount or 0 for sale in litter_sales)
        litter_cost = sum(item.amount for item in allocations if item.litter_id == litter.id)
        dog_cost = sum(item.amount for item in allocations if item.dog_id in {puppy.id for puppy in puppies})
        cost = litter_cost + dog_cost; profit = planned - cost; realized_profit = received - cost; unpaid = max(planned - received, 0)
        planned_total += planned; received_total += received; cost_total += cost
        title = f"{dam.call_name if dam else '母犬未登録'}／{litter.birth_date}"
        rows += f'<tr><td>{html.escape(title)}</td><td>{len(puppies)}頭</td><td>¥{planned:,}</td><td>¥{received:,}</td><td>¥{unpaid:,}</td><td>¥{cost:,}</td><td class="{"error" if profit < 0 else ""}">¥{profit:,}</td><td class="{"error" if realized_profit < 0 else ""}">¥{realized_profit:,}</td></tr>'
        mobile_cards += f'''<article class="calendar-mobile-card"><h3>{html.escape(title)}／{len(puppies)}頭</h3><p>販売予定 <strong>¥{planned:,}</strong>／入金 <strong>¥{received:,}</strong></p><p>原価 <strong>¥{cost:,}</strong>／予定利益 <strong class="{'error' if profit < 0 else ''}">¥{profit:,}</strong></p><p>入金基準利益 <strong class="{'error' if realized_profit < 0 else ''}">¥{realized_profit:,}</strong></p></article>'''
    unallocated_total = sum(remaining for _, remaining in remaining_expenses)
    allocation_rows = ""
    for item in allocations[:50]:
        entry = session.scalar(select(FinancialEntry).where(FinancialEntry.id == item.financial_entry_id, FinancialEntry.tenant_id == tenant.id))
        target = dogs_by_id.get(item.dog_id).call_name if item.dog_id and dogs_by_id.get(item.dog_id) else ""
        if item.litter_id and item.litter_id in litters_by_id:
            litter = litters_by_id[item.litter_id]; dam = dogs_by_id.get(litter.dam_id) or session.get(Dog, litter.dam_id); target = f"{dam.call_name if dam else '母犬未登録'} {litter.birth_date}出産"
        allocation_rows += f'<tr><td>{html.escape(entry.description if entry else "経費未登録")}</td><td>{html.escape(target or "対象未登録")}</td><td>¥{item.amount:,}</td><td>{html.escape(item.notes or "－")}</td></tr>'
    profit_total = planned_total - cost_total; realized_total = received_total - cost_total
    body = f'''<h1>原価・利益管理</h1><p>収支台帳の経費を犬・出産回へ配賦し、販売売上と比較して採算を確認します。</p>
    <div class="grid"><div class="module"><h3>販売予定額</h3><p><strong style="font-size:24px">¥{planned_total:,}</strong></p></div><div class="module"><h3>配賦済み原価</h3><p><strong style="font-size:24px">¥{cost_total:,}</strong></p></div><div class="module"><h3>予定利益</h3><p><strong class="{'error' if profit_total < 0 else ''}" style="font-size:24px">¥{profit_total:,}</strong></p></div><div class="module"><h3>入金基準利益</h3><p><strong class="{'error' if realized_total < 0 else ''}" style="font-size:24px">¥{realized_total:,}</strong></p></div><div class="module"><h3>未配賦経費</h3><p><strong style="font-size:24px">¥{unallocated_total:,}</strong></p></div></div>
    <div class="health-toolbar"><a class="button secondary" href="/modules/finance">収支・経費台帳</a><a class="button secondary" href="/modules/sales">販売管理</a></div>
    <h2>経費を配賦</h2>{f'<form method="post" action="/modules/costs"><div class="grid"><div><label>経費記録</label><select name="financial_entry_id">{expense_options}</select></div><div><label>対象犬（どちらか一方）</label><select name="dog_id">{dog_options}</select></div><div><label>対象出産回（どちらか一方）</label><select name="litter_id">{litter_options}</select></div><div><label>配賦額</label><input type="number" name="amount" min="1" required></div></div><label>配賦メモ</label><input name="notes" maxlength="500"><button>原価へ配賦する</button></form>' if remaining_expenses else '<p class="tenant">未配賦の経費はありません。収支・経費台帳で経費を登録してください。</p>'}
    <h2>出産回別の採算</h2><div class="calendar-desktop-only" style="overflow-x:auto"><table><tr><th>出産回</th><th>仔犬</th><th>販売予定</th><th>入金</th><th>未入金</th><th>原価</th><th>予定利益</th><th>入金基準利益</th></tr>{rows or '<tr><td colspan="8">出産記録はありません。</td></tr>'}</table></div><section class="calendar-mobile-only">{mobile_cards or '<div class="tenant">出産記録はありません。</div>'}</section>
    <h2>配賦履歴</h2><table><tr><th>経費</th><th>配賦先</th><th>金額</th><th>メモ</th></tr>{allocation_rows or '<tr><td colspan="4">配賦履歴はありません。</td></tr>'}</table>'''
    return layout("原価・利益管理", body, user)


@app.post("/modules/costs")
def cost_allocate(financial_entry_id: int = Form(...), amount: int = Form(...), dog_id: int | None = Form(None), litter_id: int | None = Form(None), notes: str = Form(""), access=Depends(require_tenant_user), session: Session = Depends(db)):
    user, tenant = access
    expense = session.scalar(select(FinancialEntry).where(FinancialEntry.id == financial_entry_id, FinancialEntry.tenant_id == tenant.id, FinancialEntry.entry_type == "expense"))
    dog = session.scalar(select(Dog).where(Dog.id == dog_id, Dog.tenant_id == tenant.id)) if dog_id else None
    litter = session.scalar(select(Litter).where(Litter.id == litter_id, Litter.tenant_id == tenant.id)) if litter_id else None
    allocated = session.scalar(select(func.coalesce(func.sum(CostAllocation.amount), 0)).where(CostAllocation.tenant_id == tenant.id, CostAllocation.financial_entry_id == financial_entry_id)) or 0
    if not expense or bool(dog) == bool(litter) or amount <= 0 or allocated + amount > (expense.amount if expense else 0) or len(notes) > 500:
        raise HTTPException(status_code=400, detail="原価配賦の内容を確認してください")
    ensure_finance_period_open(session, tenant.id, expense.occurred_on)
    session.add(CostAllocation(tenant_id=tenant.id, financial_entry_id=expense.id, dog_id=dog.id if dog else None, litter_id=litter.id if litter else None, amount=amount, notes=notes.strip() or None))
    session.commit()
    return RedirectResponse("/modules/costs", status_code=303)


FINANCE_DOCUMENT_TYPES = {"receipt": "領収書", "invoice": "請求書", "statement": "明細書", "other": "その他"}


@app.get("/modules/finance/documents", response_class=HTMLResponse)
def finance_documents_page(document_type: str = "", document_keyword: str = "", access=Depends(require_tenant_user), session: Session = Depends(db)):
    user, tenant = access
    if document_type not in {"", *FINANCE_DOCUMENT_TYPES} or len(document_keyword) > 100:
        raise HTTPException(status_code=400, detail="検索条件を確認してください")
    entries = session.scalars(select(FinancialEntry).where(FinancialEntry.tenant_id == tenant.id).order_by(FinancialEntry.occurred_on.desc(), FinancialEntry.id.desc())).all()
    entries_by_id = {item.id: item for item in entries}
    documents = session.scalars(select(FinanceDocument).where(FinanceDocument.tenant_id == tenant.id).order_by(FinanceDocument.uploaded_at.desc(), FinanceDocument.id.desc())).all()
    keyword = document_keyword.strip().lower()
    documents = [item for item in documents if (not document_type or item.document_type == document_type) and (not keyword or keyword in (item.issued_by or "").lower() or keyword in (item.document_no or "").lower() or keyword in item.filename.lower() or keyword in (entries_by_id.get(item.financial_entry_id).description if entries_by_id.get(item.financial_entry_id) else "").lower())]
    entry_options = "".join(f'<option value="{item.id}">{item.occurred_on}／{"入金" if item.entry_type == "income" else "経費"}／{html.escape(item.description)}／¥{item.amount:,}</option>' for item in entries)
    type_options = "".join(f'<option value="{value}" {"selected" if document_type == value else ""}>{label}</option>' for value, label in (("", "すべて"), *FINANCE_DOCUMENT_TYPES.items()))
    upload_types = "".join(f'<option value="{value}">{label}</option>' for value, label in FINANCE_DOCUMENT_TYPES.items())
    rows = ""; mobile_cards = ""
    for item in documents:
        entry = entries_by_id.get(item.financial_entry_id)
        entry_label = f"{entry.occurred_on}／{entry.description}／¥{entry.amount:,}" if entry else "台帳記録未登録"
        view = f'<a class="button secondary" href="/modules/finance/documents/{item.id}/file" target="_blank">書類を見る</a>'
        rows += f'<tr><td>{FINANCE_DOCUMENT_TYPES.get(item.document_type, item.document_type)}</td><td>{html.escape(entry_label)}</td><td>{html.escape(item.issued_by or "－")}</td><td>{html.escape(item.document_no or "－")}</td><td>{html.escape(item.filename)}</td><td>{item.uploaded_at.strftime("%Y-%m-%d")}</td><td>{view}</td></tr>'
        mobile_cards += f'''<article class="calendar-mobile-card"><h3>{FINANCE_DOCUMENT_TYPES.get(item.document_type, item.document_type)}／{html.escape(item.issued_by or "発行元未登録")}</h3><p>{html.escape(entry_label)}</p><p>番号：{html.escape(item.document_no or "－")}／{html.escape(item.filename)}</p>{view}</article>'''
    body = f'''<h1>領収書・証憑管理</h1><p>収支台帳の記録へ領収書・請求書のPDFや写真を紐づけて保管します。</p><div class="health-toolbar"><a class="button secondary" href="/modules/finance">収支・経費台帳</a><a class="button secondary" href="/modules/costs">原価・利益管理</a></div>
    <h2>書類を登録</h2>{f'<form method="post" action="/modules/finance/documents" enctype="multipart/form-data"><div class="grid"><div><label>台帳記録</label><select name="financial_entry_id">{entry_options}</select></div><div><label>書類種別</label><select name="document_type">{upload_types}</select></div><div><label>発行元</label><input name="issued_by" maxlength="150"></div><div><label>書類番号</label><input name="document_no" maxlength="100"></div></div><label>PDF・写真（8MB以下）</label><input type="file" name="document_file" accept="application/pdf,image/jpeg,image/png,image/webp" required><button>書類を登録</button></form>' if entries else '<p class="error">先に収支・経費台帳へ記録を登録してください。</p>'}
    <h2>登録済み書類</h2><form method="get" action="/modules/finance/documents"><div class="grid"><div><label>書類種別</label><select name="document_type">{type_options}</select></div><div><label>発行元・番号・ファイル名・台帳内容</label><input name="document_keyword" value="{html.escape(document_keyword)}" maxlength="100"></div></div><button>検索</button> <a class="button secondary" href="/modules/finance/documents">解除</a></form>
    <div class="calendar-desktop-only" style="overflow-x:auto"><table><tr><th>種別</th><th>台帳記録</th><th>発行元</th><th>番号</th><th>ファイル</th><th>登録日</th><th>操作</th></tr>{rows or '<tr><td colspan="7">条件に一致する書類はありません。</td></tr>'}</table></div><section class="calendar-mobile-only">{mobile_cards or '<div class="tenant">条件に一致する書類はありません。</div>'}</section>'''
    return layout("領収書・証憑管理", body, user)


@app.post("/modules/finance/documents")
async def finance_document_create(financial_entry_id: int = Form(...), document_type: str = Form(...), issued_by: str = Form(""), document_no: str = Form(""), document_file: UploadFile = File(...), access=Depends(require_tenant_user), session: Session = Depends(db)):
    user, tenant = access
    entry = session.scalar(select(FinancialEntry).where(FinancialEntry.id == financial_entry_id, FinancialEntry.tenant_id == tenant.id))
    allowed_types = {"application/pdf", "image/jpeg", "image/png", "image/webp"}
    content = await document_file.read(8 * 1024 * 1024 + 1)
    filename = Path(document_file.filename or "").name[:255]
    allowed_extensions = {"application/pdf": {".pdf"}, "image/jpeg": {".jpg", ".jpeg"}, "image/png": {".png"}, "image/webp": {".webp"}}
    suffix = Path(filename).suffix.lower()
    if not entry or document_type not in FINANCE_DOCUMENT_TYPES or document_file.content_type not in allowed_types or suffix not in allowed_extensions.get(document_file.content_type or "", set()) or not content or len(content) > 8 * 1024 * 1024 or not filename or len(issued_by) > 150 or len(document_no) > 100:
        raise HTTPException(status_code=400, detail="書類はPDF・JPG・PNG・WebPの8MB以下で登録してください")
    session.add(FinanceDocument(tenant_id=tenant.id, financial_entry_id=entry.id, document_type=document_type, issued_by=issued_by.strip() or None, document_no=document_no.strip() or None, filename=filename, content_type=document_file.content_type, file_data=content))
    session.commit()
    return RedirectResponse("/modules/finance/documents", status_code=303)


@app.get("/modules/finance/documents/{document_id}/file")
def finance_document_file(document_id: int, access=Depends(require_tenant_user), session: Session = Depends(db)):
    user, tenant = access
    item = session.scalar(select(FinanceDocument).where(FinanceDocument.id == document_id, FinanceDocument.tenant_id == tenant.id))
    if not item: raise HTTPException(status_code=404, detail="書類が見つかりません")
    return Response(content=item.file_data, media_type=item.content_type, headers={"Cache-Control": "private, no-store", "X-Content-Type-Options": "nosniff", "Content-Disposition": f"inline; filename*=UTF-8''{quote(item.filename)}"})


