        label = "誕生日" if event_type == "birthday" else "お迎え記念日"
        timing = "今日です" if days == 0 else ("明日です" if days == 1 else "7日後です")
        pseudo_time = datetime.combine(event_date, datetime.min.time(), tzinfo=ZoneInfo("Asia/Tokyo"))
